/// Feed it one value per minute (the median of that minute). Call [reset] after a gap of more than 2 minutes.
class VitalsMonitor {
  VitalsMonitor(this.signal);

  final VitalSignal signal;
  final List<double> _hist = <double>[];
  final List<double> _absResid = <double>[];
  final List<bool> _flags = <bool>[];

  /// null for an implausible value (a sensor artefact is ignored) and while there is not enough history.
  VitalsDecision? addMinute(double v) {
    if (v.isNaN || !VitalsModel.plausible(signal, v)) return null;
    VitalsDecision? out;
    const n = VitalsModel.historyMinutes;
    if (_hist.length >= n) {
      final w = _hist.sublist(_hist.length - n);
      final c = VitalsModel.median(w);
      final scale = VitalsModel.scaleOf(signal);
      final rel = <double>[for (final x in w) (x - c) / scale];
      final f = VitalsModel.forecast(signal, rel);
      final expected = c + (f ?? 0.0) * scale;
      var sigma = VitalsModel.sigmaOf(signal) * scale;
      if (!VitalsModel.trained && _absResid.length >= 10) {
        // without a trained network the typical error is learned from the last two hours
        sigma = math.max(sigma, 1.4826 * VitalsModel.median(_absResid));
      }
      final z = (v - expected) / sigma;
      final unusual = z.abs() > VitalsModel.zLimitOf(signal);
      _flags.add(unusual);
      if (_flags.length > VitalsModel.alertWindows) _flags.removeAt(0);
      _absResid.add((v - expected).abs());
      if (_absResid.length > 120) _absResid.removeAt(0);
      out = VitalsDecision(
        value: v,
        expected: expected,
        z: z,
        unusual: unusual,
        alert: _flags.where((e) => e).length >= VitalsModel.alertNeeded,
      );
    }
    _hist.add(v);
    if (_hist.length > n) _hist.removeAt(0);
    return out;
  }

  void reset() {
    _hist.clear();
    _absResid.clear();
    _flags.clear();
  }
}
